const command = $input.item.json.command;
const userId = $input.item.json.id;
const chatId = $input.item.json.chatId;

// Enhanced command handling
switch(command) {
  case '/start':
    return {
      json: {
        chatId,
        response: '🇳🇴 Welcome to Enhanced Norsk Cards Bot!\n\n📸 Send a photo - I\'ll identify objects\n📝 Send Ukrainian text - I\'ll translate to Norwegian\n🎤 Send voice message - I\'ll process speech\n📚 Use commands:\n/stats - Your learning progress\n/review - Practice words\n/help - Full instructions\n/settings - Preferences',
        action: 'send_message'
      }
    };

  case '/help':
    return {
      json: {
        chatId,
        response: '🔧 Enhanced Features:\n\n📸 Photo Recognition\n📝 Text Translation (Ukrainian→Norwegian)\n🎤 Voice Processing\n📊 Progress Tracking\n🔄 Batch Processing\n📋 IPA Transcription\n💾 Auto-save to Google Sheets\n\n🎯 Commands:\n/stats - Learning statistics\n/review - Practice session\n/settings - User preferences',
        action: 'send_message'
      }
    };

  case '/stats':
    return {
      json: {
        chatId,
        userId,
        action: 'get_stats'
      }
    };

  case '/review':
    return {
      json: {
        chatId,
        userId,
        action: 'get_review'
      }
    };

  case '/settings':
    return {
      json: {
        chatId,
        response: '⚙️ Settings:\n\n🔊 Audio enabled: Yes\n📝 IPA transcription: Yes\n🎯 Difficulty level: Intermediate\n📊 Progress tracking: Enabled\n\nUse inline buttons to modify settings.',
        action: 'send_message'
      }
    };

  default:
    return {
      json: {
        chatId,
        response: '❓ Unknown command. Use /help for available commands.',
        action: 'send_message'
      }
    };
}

// Enhanced response processing with error handling
try {
  const response = $input.first().json.response || $input.first().json.text;
  let data;

  // Robust JSON parsing
  try {
    data = JSON.parse(response);
  } catch (e) {
    const jsonMatch = response.match(/{[\s\S]*?}/);
    if (jsonMatch) {
      data = JSON.parse(jsonMatch[0]);
    } else {
      throw new Error('No valid JSON found in response');
    }
  }

  // Enhanced validation
  const requiredFields = ['word_no', 'word_en', 'word_uk', 'examples'];
  const missingFields = requiredFields.filter(field => !data[field]);

  if (missingFields.length > 0) {
    throw new Error(`Missing required fields: ${missingFields.join(', ')}`);
  }

  // Get previous node data safely
  const inputAnalyzer = $('Code_Input_Analyzer').first().json;

  // Enrich data with metadata
  const enrichedData = {
    ...data,
    processingId: inputAnalyzer.processingId,
    userId: inputAnalyzer.id,
    userName: inputAnalyzer.name,
    chatId: inputAnalyzer.chatId,
    inputType: inputAnalyzer.inputType,
    timestamp: new Date().toISOString(),
    confidence: 'high',
    source: 'primary_llm'
  };

  return { json: enrichedData };

} catch (error) {
  const inputAnalyzer = $('Code_Input_Analyzer').first().json;
  return {
    json: {
      error: true,
      errorMessage: error.message,
      processingId: inputAnalyzer.processingId,
      chatId: inputAnalyzer.chatId,
      fallbackNeeded: true
    }
  };
}

// Comprehensive error handling and fallback logic
const input = $input.item.json;

if (input.error) {
  // Try fallback LLM or provide graceful degradation
  return {
    json: {
      chatId: input.chatId,
      text: '⚠️ Processing temporarily unavailable. Please try again or contact support.',
      error: true,
      fallbackAction: 'retry_later'
    }
  };
}

// Success path - prepare for parallel operations
return {
  json: {
    ...input,
    readyForStorage: true,
    readyForResponse: true
  }
};

const item = JSON.parse(JSON.stringify($input.item));

// Check if we have binary data
if (item.binary && item.binary.data) {
  // Fix the MIME type
  item.binary.data.mimeType = 'image/jpeg';

  // If the file has a .jpg or .jpeg extension
  if (item.binary.data.fileName.endsWith('.jpg') || item.binary.data.fileName.endsWith('.jpeg')) {
    item.binary.data.mimeType = 'image/jpeg';
  }
  // If the file has a .png extension
  else if (item.binary.data.fileName.endsWith('.png')) {
    item.binary.data.mimeType = 'image/png';
  }
}

return {json: item.json, binary: item.binary};

// Parse the JSON from the LLM response
let responseData;
try {
  const responseText = $input.item.json.response || $input.item.json.text;

  // Try to parse the JSON response
  try {
    responseData = JSON.parse(responseText);
  } catch (e) {
    // If direct parsing fails, try to extract JSON from text
    const jsonMatch = responseText.match(/```json\s*([\s\S]*?)\s*```/) || 
                     responseText.match(/```\s*([\s\S]*?)\s*```/) || 
                     responseText.match(/{[\s\S]*?}/);

    if (jsonMatch) {
      responseData = JSON.parse(jsonMatch[0]);
    } else {
      throw new Error("Could not find JSON in response");
    }
  }

} catch (error) {
  return {
    json: {
      chatId: $input.item.json.chatId,
      error: "Could not parse LLM response: " + error.message,
      raw_response: $input.item.json.response
    }
  };
}

return {
  json: {
    chatId: $input.item.json.chatId,
    messageId: $input.item.json.messageId,
    word_no: responseData.word_no,
    word_no_IPA: responseData.word_no_IPA,
    word_en: responseData.word_en,
    word_uk: responseData.word_uk,
    examples: responseData.examples || [],
    examples_IPA: responseData.examples_IPA || [],
    examples_UKR: responseData.examples_UKR || [],
    original_type: "image",
  }
};

